// Fails on named imports that the file never uses.
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

const files = (d) => readdirSync(d).flatMap((f) => {
  const p = join(d, f);
  return statSync(p).isDirectory() ? files(p) : p.endsWith(".js") ? [p] : [];
});
let bad = 0;
for (const f of [...files("src"), ...files("test")]) {
  const text = readFileSync(f, "utf8");
  for (const m of text.matchAll(/^import \{([^}]*)\} from/gm)) {
    for (const name of m[1].split(",").map((s) => s.trim().split(/\s+as\s+/).pop()).filter(Boolean)) {
      const uses = text.split(new RegExp(`\\b${name}\\b`)).length - 1;
      if (uses < 2) { console.error(`${f}: '${name}' is imported but never used`); bad++; }
    }
  }
}
process.exit(bad ? 1 : 0);

