import { legacyGet } from "./util/http.js";

// Reports come back with the CSV as a base64 string.
export async function fetchReport(client, id) {
  const body = await legacyGet(client.baseUrl, `/reports/${id}`);
  return { ...body, csv: new Buffer(body.csvBase64, "base64").toString("utf8") };
}

