import { test } from "node:test";
import assert from "node:assert/strict";
import { fetchReport } from "../src/reports.js";

test("fetchReport decodes the CSV", async (t) => {
  const csvBase64 = Buffer.from("a,b\n1,2\n").toString("base64");
  t.mock.method(globalThis, "fetch", async () => ({ ok: true, status: 200, json: async () => ({ id: 9, csvBase64 }) }));
  const report = await fetchReport({ baseUrl: "https://x" }, 9);
  assert.equal(report.csv, "a,b\n1,2\n");
});
